def maximumSum(nums):
    from collections import Counter
    # bucket by remainder mod 3, each kept in descending order
    g = {0: [], 1: [], 2: []}
    for x in nums:
        g[x % 3].append(x)
    for r in g:
        g[r].sort(reverse=True)
    # remainder multisets whose total is divisible by 3
    best = -1
    for combo in [(0, 0, 0), (1, 1, 1), (2, 2, 2), (0, 1, 2)]:
        need = Counter(combo)
        if all(len(g[r]) >= c for r, c in need.items()):
            total = sum(sum(g[r][:c]) for r, c in need.items())
            best = max(best, total)
    return best if best >= 0 else 0
